import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const c=JSON.parse('{"title":"Проблемы администратора","description":"","frontmatter":{"pageId":"admins/troubleshooting","contentRevision":1},"headers":[],"relativePath":"ru/admins/troubleshooting.md","filePath":"ru/admins/troubleshooting.md"}'),i={name:"ru/admins/troubleshooting.md"};function n(s,a,l,d,h,p){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="проблемы-администратора" tabindex="-1">Проблемы администратора <a class="header-anchor" href="#проблемы-администратора" aria-label="Permalink to &quot;Проблемы администратора&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p><strong>Сервер не стартует:</strong> проверь SDK/runtime, права DataDir, занятый порт, сертификат и сообщение валидации Options. Не устраняй ошибку удалением БД.</p><p><strong>Панель работает, игра нет:</strong> проверь HTTP/2/gRPC, прокси, TLS и игровые версии. Простая загрузка HTML проверяет не весь транспорт.</p><p><strong>401/403:</strong> сверяй legacy/именованный токен, scopes, cookie CSRF и срок сессии; не повышай интеграцию до admin без причины.</p><p><strong>Зависший расчёт:</strong> проверь заморозку, долг, угрозу, срок и id эскроу; изучи аудит и состояние до повторения мутации.</p><p><strong>Не проходит restore:</strong> остановлен ли сервер, цела ли копия, совпадают ли БД/сейвы; сохрани текущие данные до дальнейших действий.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Не выводи секреты окружения в общий тикет. Не завершай чужие процессы. Если причина неизвестна, собери точный отказ, версию, время и обезличенный фрагмент лога; не объявляй проблему решённой по одному /health.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./monitoring">Мониторинг и журнал событий</a></li><li><a href="./backup-recovery">Резервные копии и восстановление</a></li><li><a href="./../players/troubleshooting">Проблемы игрока</a></li></ul>',12)])])}const m=e(i,[["render",n]]);export{c as __pageData,m as default};
